  void p(){   
   try{   
    n();   
   }catch(Exception e){System.out.println("exception handled");}   
  }   
  public static void main(String args[]){   
   Testthrows1 obj=new Testthrows1();   
   obj.p();   
   System.out.println("normal flow...");   
  }   
}   
